  // end that may be an at-ms, an interval in ms
  const byUser = !deviceCode && !!userCode && expiredIn !== undefined
  const uri = str(b, "verification_uri") ?? str(b, "verification_url")
  const at = expiredIn === undefined ? undefined : expired
